import React, { useState, useEffect } from 'react';
import { facultyApi, departmentsApi, subjectsApi } from '../services/api';
import './Faculty.css';

function Faculty() {
  const [list, setList] = useState([]);
  const [departments, setDepartments] = useState([]);
  const [subjects, setSubjects] = useState([]);
  const [loading, setLoading] = useState(true);
  const [modal, setModal] = useState(null);
  const [form, setForm] = useState({
    facultyId: '', name: '', homeDepartment: '', subjectsHandled: [], maxPeriodsPerDay: 6, maxPeriodsPerWeek: 30
  });
  const [message, setMessage] = useState(null);

  const load = () => {
    facultyApi.getAll().then(setList).catch(() => setList([]));
    departmentsApi.getAll().then(setDepartments).catch(() => setDepartments([]));
    subjectsApi.getAll().then(setSubjects).catch(() => setSubjects([]));
  };

  useEffect(() => {
    load();
    setLoading(false);
  }, []);

  useEffect(() => {
    if (modal) {
      departmentsApi.getAll().then(setDepartments).catch(() => {});
      subjectsApi.getAll().then(setSubjects).catch(() => {});
    }
  }, [modal]);

  const openCreate = () => {
    setForm({
      facultyId: '', name: '', homeDepartment: '', subjectsHandled: [],
      maxPeriodsPerDay: 6, maxPeriodsPerWeek: 30
    });
    setModal('create');
    setMessage(null);
  };

  const openEdit = (f) => {
    setForm({
      id: f._id,
      facultyId: f.facultyId,
      name: f.name,
      homeDepartment: f.homeDepartment?._id || f.homeDepartment || '',
      subjectsHandled: (f.subjectsHandled || []).map(s => s._id || s),
      maxPeriodsPerDay: f.maxPeriodsPerDay ?? 6,
      maxPeriodsPerWeek: f.maxPeriodsPerWeek ?? 30
    });
    setModal('edit');
    setMessage(null);
  };

  const toggleSubject = (id) => {
    setForm(prev => ({
      ...prev,
      subjectsHandled: prev.subjectsHandled.includes(id)
        ? prev.subjectsHandled.filter(x => x !== id)
        : [...prev.subjectsHandled, id]
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setMessage(null);
    const payload = {
      facultyId: form.facultyId,
      name: form.name,
      homeDepartment: form.homeDepartment,
      subjectsHandled: form.subjectsHandled,
      maxPeriodsPerDay: Number(form.maxPeriodsPerDay) || 6,
      maxPeriodsPerWeek: Number(form.maxPeriodsPerWeek) || 30
    };
    if (modal === 'create') {
      facultyApi.create(payload)
        .then(() => { setModal(null); load(); setMessage({ type: 'success', text: 'Faculty created.' }); })
        .catch((err) => setMessage({ type: 'error', text: err.message }));
    } else {
      facultyApi.update(form.id, payload)
        .then(() => { setModal(null); load(); setMessage({ type: 'success', text: 'Faculty updated.' }); })
        .catch((err) => setMessage({ type: 'error', text: err.message }));
    }
  };

  const handleDelete = (id) => {
    if (!window.confirm('Delete this faculty?')) return;
    facultyApi.delete(id).then(() => load()).catch((err) => setMessage({ type: 'error', text: err.message }));
  };

  if (loading) return <div className="page-loading">Loading...</div>;

  return (
    <div className="faculty-page">
      <div className="page-header">
        <h1>Faculty</h1>
        <button type="button" className="btn btn-primary" onClick={openCreate}>Add Faculty</button>
      </div>
      {message && <div className={`alert alert-${message.type === 'success' ? 'success' : 'error'}`}>{message.text}</div>}
      <div className="table-wrap card">
        {list.length === 0 ? (
          <div className="empty-state"><p>No faculty yet. Add one to get started.</p></div>
        ) : (
          <table>
            <thead>
              <tr>
                <th>ID</th>
                <th>Name</th>
                <th>Home Dept</th>
                <th>Max/Day</th>
                <th>Max/Week</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {list.map((f) => (
                <tr key={f._id}>
                  <td>{f.facultyId}</td>
                  <td>{f.name}</td>
                  <td>{f.homeDepartment?.name || '-'}</td>
                  <td>{f.maxPeriodsPerDay}</td>
                  <td>{f.maxPeriodsPerWeek}</td>
                  <td>
                    <button type="button" className="btn btn-sm btn-secondary" onClick={() => openEdit(f)}>Edit</button>
                    <button type="button" className="btn btn-sm btn-danger" onClick={() => handleDelete(f._id)}>Delete</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      {modal && (
        <div className="modal-overlay" onClick={() => setModal(null)}>
          <div className="modal modal-lg card" onClick={(e) => e.stopPropagation()}>
            <h2>{modal === 'create' ? 'Add Faculty' : 'Edit Faculty'}</h2>
            {message && <div className={`alert alert-${message.type === 'success' ? 'success' : 'error'}`}>{message.text}</div>}
            <form onSubmit={handleSubmit}>
              <div className="form-row">
                <div className="form-group">
                  <label>Faculty ID</label>
                  <input
                    required
                    value={form.facultyId}
                    onChange={(e) => setForm(prev => ({ ...prev, facultyId: e.target.value }))}
                    placeholder="e.g. F001"
                    disabled={modal === 'edit'}
                  />
                </div>
                <div className="form-group">
                  <label>Name</label>
                  <input
                    required
                    value={form.name}
                    onChange={(e) => setForm(prev => ({ ...prev, name: e.target.value }))}
                    placeholder="Full name"
                  />
                </div>
              </div>
              <div className="form-group">
                <label>Home Department</label>
                <select
                  required
                  value={form.homeDepartment}
                  onChange={(e) => setForm(prev => ({ ...prev, homeDepartment: e.target.value }))}
                >
                  <option value="">Select department</option>
                  {departments.map((d) => (
                    <option key={d._id} value={d._id}>{d.name} ({d.departmentId})</option>
                  ))}
                </select>
              </div>
              <div className="form-group">
                <label>Subjects handled</label>
                <div className="subject-chips">
                  {subjects.map((s) => (
                    <label key={s._id} className="subject-chip">
                      <input
                        type="checkbox"
                        checked={form.subjectsHandled.includes(s._id)}
                        onChange={() => toggleSubject(s._id)}
                      />
                      <span>{s.name} (Sem {s.semester})</span>
                    </label>
                  ))}
                  {subjects.length === 0 && <span className="text-muted">No subjects defined yet.</span>}
                </div>
              </div>
              <div className="form-row">
                <div className="form-group">
                  <label>Max periods per day</label>
                  <input
                    type="number"
                    min={1}
                    max={8}
                    value={form.maxPeriodsPerDay}
                    onChange={(e) => setForm(prev => ({ ...prev, maxPeriodsPerDay: Number(e.target.value) || 6 }))}
                  />
                </div>
                <div className="form-group">
                  <label>Max periods per week</label>
                  <input
                    type="number"
                    min={1}
                    max={40}
                    value={form.maxPeriodsPerWeek}
                    onChange={(e) => setForm(prev => ({ ...prev, maxPeriodsPerWeek: Number(e.target.value) || 30 }))}
                  />
                </div>
              </div>
              <div className="modal-actions">
                <button type="button" className="btn btn-secondary" onClick={() => setModal(null)}>Cancel</button>
                <button type="submit" className="btn btn-primary">Save</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

export default Faculty;
